function isUsableState(state) {
  return state !== undefined && state !== null && state !== 'unavailable' && state !== 'unknown' && state !== '';
}

function keyMatches(translationKey, slot) {
  if (!translationKey) return false;
  if (slot.keys?.includes(translationKey)) return true;
  if (!slot.keyPrefix) return false;
  return translationKey === slot.keyPrefix || translationKey.startsWith(`${slot.keyPrefix}_`);
}

class EntityHelpers {
  static getAnchorEntityId(config) {
    const name = config?.device_name || '';
    return name.includes('.') ? name : null;
  }

  static getLegacyPrefix(config) {
    const name = config?.device_name || config?.entity_prefix || '';
    if (!name) return '';
    if (name.includes('.')) return name.split('.').slice(1).join('.');
    return name;
  }

  static getEntity(hass, entityId) {
    if (!entityId || !hass?.states) return null;
    const entity = hass.states[entityId];
    if (!entity || !isUsableState(entity.state)) return null;
    return entity;
  }

  static getEntityValue(hass, entityId, defaultValue) {
    const entity = this.getEntity(hass, entityId);
    return entity ? entity.state : defaultValue;
  }

  static getState(hass, entityId) {
    return this.getEntityValue(hass, entityId, null);
  }

  static formatToggle(hass, entityId) {
    const entity = this.getEntity(hass, entityId);
    if (!entity) return null;
    const isOn = entity.state === 'on';
    if (entity.attributes?.device_class === 'lock') {
      return isOn ? 'Unlocked' : 'Locked';
    }
    return isOn ? 'On' : 'Off';
  }

  static readSensor(hass, entityId, fallbackUnit) {
    const entity = this.getEntity(hass, entityId);
    if (!entity) return { value: null, unit: fallbackUnit || '' };
    return {
      value: entity.state,
      unit: entity.attributes?.unit_of_measurement || fallbackUnit || '',
    };
  }

  static collectDeviceEntityIds(hass, anchorId) {
    const registry = hass?.entities;
    if (!registry || !anchorId || !registry[anchorId]?.device_id) return [];
    const deviceId = registry[anchorId].device_id;
    return Object.keys(registry).filter((id) => registry[id]?.device_id === deviceId);
  }

  static findByTranslationKey(hass, entityIds, slot) {
    const matches = entityIds.filter((id) => {
      const domain = id.split('.')[0];
      if (slot.domains && !slot.domains.includes(domain)) return false;
      return keyMatches(hass.entities?.[id]?.translation_key, slot);
    });
    if (!matches.length) return null;

    const preferred = slot.preferDomain
      ? matches.find((id) => id.startsWith(`${slot.preferDomain}.`))
      : null;
    const available = matches.find((id) => this.getEntity(hass, id));
    return preferred && this.getEntity(hass, preferred)
      ? preferred
      : available || preferred || matches[0];
  }

  static resolveEntityId(hass, config, slotName, deviceEntityIds, prefix) {
    const slot = SLOT_DEFS[slotName];
    const configuredId = slot.configKey ? config?.[slot.configKey] : '';
    if (configuredId) return configuredId;

    const matched = this.findByTranslationKey(hass, deviceEntityIds, slot);
    if (matched) return matched;

    if (slot.legacySuffix && slot.legacyDomain && prefix) {
      return `${slot.legacyDomain}.${prefix}_${slot.legacySuffix}`;
    }
    return null;
  }

  static getDisplayName(hass, config) {
    const anchorId = this.getAnchorEntityId(config);
    const deviceId = anchorId && hass?.entities?.[anchorId]?.device_id;
    const device = deviceId && hass?.devices?.[deviceId];
    if (device?.name_by_user) return device.name_by_user;
    if (device?.name) return device.name;
    const friendlyName = anchorId && hass?.states?.[anchorId]?.attributes?.friendly_name;
    if (friendlyName) return friendlyName;
    return null;
  }

  static getAllSensorData(hass, config) {
    const prefix = this.getLegacyPrefix(config);
    const anchorId = this.getAnchorEntityId(config);
    const deviceEntityIds = this.collectDeviceEntityIds(hass, anchorId);
    const resolve = (slotName) => this.resolveEntityId(hass, config, slotName, deviceEntityIds, prefix);

    const energy = this.readSensor(hass, resolve('energy'), SLOT_DEFS.energy.fallbackUnit);
    const energySaved = this.readSensor(hass, resolve('energySaved'), SLOT_DEFS.energySaved.fallbackUnit);
    const power = this.readSensor(hass, resolve('power'), SLOT_DEFS.power.fallbackUnit);
    const water = this.readSensor(hass, resolve('water'), SLOT_DEFS.water.fallbackUnit);
    const cycleState = this.getState(hass, resolve('cycleActive'));

    return {
      machineState: this.getState(hass, resolve('machineState')) || 'Unknown',
      progress: this.getState(hass, resolve('progress')),
      cycleActive: cycleState === null ? null : cycleState === 'on',
      jobState: this.getState(hass, resolve('jobState')),
      completionTime: this.getState(hass, resolve('completionTime')),
      energy: energy.value,
      energyUnit: energy.unit,
      energySaved: energySaved.value,
      energySavedUnit: energySaved.unit,
      power: power.value,
      powerUnit: power.unit,
      waterConsumption: water.value,
      waterUnit: water.unit,
      powerBinary: this.formatToggle(hass, resolve('powerBinary')),
      washerSelect: this.getState(hass, resolve('program')),
      childLock: this.formatToggle(hass, resolve('childLock')),
      remoteControl: this.formatToggle(hass, resolve('remoteControl')),
      bubbleSoak: this.formatToggle(hass, resolve('bubbleSoak')),
      detergentAmount: this.getState(hass, resolve('detergent')),
      rinseCycles: this.getState(hass, resolve('rinseCycles')),
      spinLevel: this.getState(hass, resolve('spinLevel')),
    };
  }
}

// Formatter utility functions
const IN_CYCLE_STAGES = new Set([
  'wash',
  'washing',
  'rinse',
  'rinsing',
  'spin',
  'spinning',
  'dry',
  'drying',
  'prewash',
  'pre wash',
  'weight sensing',
  'weightsensing',
  'delaywash',
  'delay wash',
  'soak',
]);

const PAUSED_STATES = new Set(['pause', 'paused']);
const FINISHED_STAGES = new Set(['finish', 'finished']);

class Formatters {
  static formatDeviceName(deviceName) {
    return String(deviceName || '')
      .split('_')
      .filter(Boolean)
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
      .join(' ');
  }

  static normalizeState(value) {
    return String(value || '')
      .trim()
      .toLowerCase()
      .replace(/[_-]+/g, ' ')
      .replace(/\s+/g, ' ');
  }

  static formatStage(value) {
    if (value == null || value === '') return null;
    return this.normalizeState(value).replace(/\b\w/g, (letter) => letter.toUpperCase());
  }

  static formatCompletionTime(timeStr) {
    if (!timeStr || timeStr === 'Unknown' || timeStr === 'unavailable') return null;

    const date = new Date(timeStr);
    if (Number.isNaN(date.getTime())) return null;

    const diffMs = date.getTime() - Date.now();
    const elapsed = Math.abs(diffMs);
    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const clock = hours > 0 ? `${hours}h ${minutes}m` : `${minutes}m`;
    return diffMs < 0 ? `${clock} ago` : `${clock} left`;
  }

  static formatSensorValue(value) {
    if (value == null || value === '') return null;
    const number = Number(value);
    if (!Number.isFinite(number)) return value;
    if (Number.isInteger(number)) return String(number);
    return String(parseFloat(number.toFixed(2)));
  }

  static formatSpin(value) {
    if (value == null || value === '') return '—';
    const text = String(value).trim();
    return /^-?\d+(\.\d+)?$/.test(text) ? `${text} RPM` : text;
  }

  static getIconHtml(icon) {
    return icon.includes(':')
      ? `<ha-icon icon="${icon}"></ha-icon>`
      : icon;
  }

  static isFinishedStage(progress) {
    return FINISHED_STAGES.has(this.normalizeState(progress));
  }

  static getActivity(sensorData) {
    const state = this.normalizeState(sensorData?.machineState);
    const stage = this.normalizeState(sensorData?.progress);

    if (PAUSED_STATES.has(state) || PAUSED_STATES.has(stage)) return 'paused';
    if (FINISHED_STAGES.has(stage)) return 'idle';
    if (IN_CYCLE_STAGES.has(stage)) return 'running';
    if (state === 'active' || state.includes('running') || state.includes('wash')) return 'running';
    if (sensorData?.cycleActive === true) return 'running';
    return 'idle';
  }

  static getStatusClass(activity, machineState, progress) {
    if (activity === 'running') return 'status-running';
    if (activity === 'paused') return 'status-paused';
    if (this.isFinishedStage(progress) || this.normalizeState(machineState).includes('stopped')) {
      return 'status-stopped';
    }
    return 'status-idle';
  }

  static getAnimationClass(activity, isRecentlyCompleted) {
    if (activity === 'running') return 'running';
    if (isRecentlyCompleted) return 'completed';
    return '';
  }

  static getStatusLightClass(activity, isRecentlyCompleted) {
    if (activity === 'running') return 'running';
    if (isRecentlyCompleted) return 'completed';
    return 'idle';
  }

  static getStatusText(sensorData) {
    const program = sensorData?.washerSelect;
    if (program && program !== 'Unknown') return program;

    const state = this.normalizeState(sensorData?.machineState);
    const stage = sensorData?.progress;
    const stageKey = this.normalizeState(stage);
    const machineIsGeneric = !state || state === 'active' || state === 'unknown' || state === 'idle';
    if (machineIsGeneric && stageKey && stageKey !== 'none' && stageKey !== 'unknown' && stageKey !== 'idle') {
      return this.formatStage(stage);
    }
    return sensorData?.machineState || 'Unknown';
  }

  static nextRememberedFinish({ live, remembered, finishWasLive, activity, now }) {
    if (live && !Number.isNaN(new Date(live).getTime())) {
      return { remembered: live, finishWasLive: true };
    }

    if (finishWasLive && activity !== 'running' && activity !== 'paused') {
      const rememberedMs = remembered ? new Date(remembered).getTime() : NaN;
      const next = Number.isFinite(rememberedMs) && rememberedMs <= now
        ? remembered
        : new Date(now).toISOString();
      return { remembered: next, finishWasLive: false };
    }

    return { remembered: remembered || null, finishWasLive: Boolean(finishWasLive) };
  }

  static isWithinCompletionWindow(timestamp, hours, now) {
    if (!timestamp) return false;
    const completionMs = new Date(timestamp).getTime();
    if (Number.isNaN(completionMs)) return false;
    const diffMs = now - completionMs;
    return diffMs >= 0 && diffMs <= hours * 60 * 60 * 1000;
  }
}

class SamsungWasherCard extends HTMLElement {
  set hass(hass) {
    // Store hass reference for use in other methods
    this.currentHass = hass;
    
    if (!this.content) {
      this.innerHTML = `
        <ha-card>
          <div class="card-content"></div>
          <style>
            ${baseStyles}
            ${animationStyles}
            ${responsiveStyles}
          </style>
        </ha-card>
      `;
      this.content = this.querySelector(".card-content");
    }

    const sensorData = EntityHelpers.getAllSensorData(hass, this.config);
    const activity = Formatters.getActivity(sensorData);
    const isRecentlyCompleted = this.isRecentlyCompleted(sensorData, activity);
    const completionSource = sensorData.completionTime
      || (isRecentlyCompleted ? this._lastFinishTime : null);
    const formattedCompletionTime = Formatters.formatCompletionTime(completionSource);

    const statusClass = Formatters.getStatusClass(activity, sensorData.machineState, sensorData.progress);
    const animationClass = Formatters.getAnimationClass(activity, isRecentlyCompleted);
    const statusLightClass = Formatters.getStatusLightClass(activity, isRecentlyCompleted);

    const legacyName = Formatters.formatDeviceName(EntityHelpers.getLegacyPrefix(this.config) || 'washer');
    const deviceDisplayName = EntityHelpers.getDisplayName(hass, this.config) || legacyName;
    
    const washerIcon = this.config.icon || '🧺';
    const iconHtml = Formatters.getIconHtml(washerIcon);

    const sensorsGridData = {
      completionTime: formattedCompletionTime,
      energy: Formatters.formatSensorValue(sensorData.energy),
      energyUnit: sensorData.energyUnit,
      waterConsumption: Formatters.formatSensorValue(sensorData.waterConsumption),
      waterUnit: sensorData.waterUnit,
      powerBinary: sensorData.powerBinary,
      power: Formatters.formatSensorValue(sensorData.power),
      powerUnit: sensorData.powerUnit,
      energySaved: Formatters.formatSensorValue(sensorData.energySaved),
      energySavedUnit: sensorData.energySavedUnit,
      jobState: Formatters.formatStage(sensorData.jobState)
    };

    const controlsData = {
      childLock: sensorData.childLock,
      remoteControl: sensorData.remoteControl,
      bubbleSoak: sensorData.bubbleSoak,
      detergentAmount: sensorData.detergentAmount,
      rinseCycles: sensorData.rinseCycles,
      spinLevel: Formatters.formatSpin(sensorData.spinLevel)
    };

    const statusText = Formatters.getStatusText(sensorData);

    // Render the card
    this.content.innerHTML = `
      <div class="washer-layout">
        <div class="washer-left">
          <div class="washer-header">
            <div class="washer-icon">${iconHtml}</div>
            <div class="washer-title">
              <h2 class="washer-name">${deviceDisplayName}</h2>
              <p class="washer-status">
                <span class="status-badge ${statusClass}">${statusText}</span>
              </p>
            </div>
          </div>

          ${createWashingMachine(animationClass, statusLightClass)}
        </div>
        
        <div class="washer-right">
          ${createSensorsGrid(sensorsGridData)}
          ${createControlsSection(controlsData)}
        </div>
      </div>
    `;
  }

  isRecentlyCompleted(sensorData, activity) {
    const now = Date.now();
    const remembered = Formatters.nextRememberedFinish({
      live: sensorData.completionTime,
      remembered: this._lastFinishTime,
      finishWasLive: this._finishWasLive,
      activity,
      now,
    });
    this._lastFinishTime = remembered.remembered;
    this._finishWasLive = remembered.finishWasLive;

    if (activity === 'running' || activity === 'paused') return false;
    if (Formatters.isFinishedStage(sensorData.progress)) return true;

    const configuredHours = Number(this.config.complete_status_for_x_hours);
    const hours = Number.isFinite(configuredHours) && configuredHours > 0 ? configuredHours : 2;
    return Formatters.isWithinCompletionWindow(
      sensorData.completionTime || this._lastFinishTime,
      hours,
      now
    );
  }

  // The user supplied configuration. Throw an exception and Home Assistant
  // will render an error card.
  setConfig(config) {
    if (!config.entity_prefix && !config.device_name) {
      throw new Error("You need to define either entity_prefix or device_name");
    }
    this.config = config;
  }

  // The height of your card. Home Assistant uses this to automatically
  // distribute all cards over the available columns in masonry view
  getCardSize() {
    return 12;
  }

  // The rules for sizing your card in the grid in sections view
  getGridOptions() {
    return {
      rows: 8,
      columns: 12,
      min_rows: 8,
      max_rows: 8,
      min_columns: 12,
      max_columns: 12,
    };
  }

  // Return the stub configuration for the card
  static getStubConfig(hass) {
    let defaultDeviceName = "";
    if (hass?.entities) {
      const localThingsEntity = Object.keys(hass.entities).find((entityId) => {
        const entry = hass.entities[entityId];
        const key = entry?.translation_key || '';
        return entry?.platform === 'localthings' && (
          key === 'machine_state' || key === 'washer_cycle' || key.startsWith('washer_cycle_')
        );
      });
      if (localThingsEntity) defaultDeviceName = localThingsEntity;
    }

    if (!defaultDeviceName && hass?.states) {
      const selectEntities = Object.keys(hass.states).filter((entity) =>
        entity.startsWith('select.') &&
        (entity.toLowerCase().includes('wash') ||
         entity.toLowerCase().includes('washer') ||
         entity.toLowerCase().includes('laundry'))
      );
      if (selectEntities.length > 0) defaultDeviceName = selectEntities[0];
    }
    
    return {
      device_name: defaultDeviceName,
      icon: "🧺",
      complete_status_for_x_hours: 2
    };
  }

  // Use built-in form editor with selectors
  static getConfigForm(hass, config) {
    // Convert device_name to full entity ID for the selector
    const currentEntityId = config?.device_name?.includes('.') 
      ? config.device_name 
      : (config?.device_name ? `select.${config.device_name}` : '');
    
    return {
      schema: [
        {
          name: "device_name",
          required: true,
          selector: {
            entity: {
              filter: [
                { domain: "sensor" },
                { domain: "binary_sensor" },
                { domain: "switch" },
                { domain: "select" },
                { domain: "number" },
                { domain: "button" }
              ]
            }
          },
          // This is a workaround to show the current value
          default: currentEntityId
        },
        {
          name: "completion_time_entity",
          selector: {
            entity: {
              domain: "sensor"
            }
          }
        },
        {
          name: "energy_entity",
          selector: {
            entity: {
              domain: "sensor",
              device_class: "energy"
            }
          }
        },
        {
          name: "water_entity",
          selector: {
            entity: {
              domain: "sensor"
            }
          }
        },
        {
          name: "power_binary_entity",
          selector: {
            entity: {
              domain: "binary_sensor"
            }
          }
        },
        {
          name: "power_entity",
          selector: {
            entity: {
              domain: "sensor",
              device_class: "power"
            }
          }
        },
        {
          name: "energy_saved_entity",
          selector: {
            entity: {
              domain: "sensor",
              device_class: "energy"
            }
          }
        },
        {
          name: "job_state_entity",
          selector: {
            entity: {
              domain: "sensor"
            }
          }
        },
        {
          name: "program_entity",
          selector: {
            entity: {
              domain: "select"
            }
          }
        },
        {
          name: "icon",
          selector: {
            icon: {}
          }
        },
        {
          name: "complete_status_for_x_hours",
          default: 2,
          selector: {
            number: {
              min: 1,
              max: 24,
              mode: "box",
              unit_of_measurement: "hours"
            }
          }
        }
      ],
      computeLabel: (schema) => {
        const labels = {
          device_name: "Washer Entity",
          completion_time_entity: "Completion Time Sensor",
          energy_entity: "Energy Sensor",
          water_entity: "Water Consumption Sensor",
          power_binary_entity: "Power Status (Binary)",
          power_entity: "Power Sensor",
          energy_saved_entity: "Energy Saved Sensor",
          job_state_entity: "Job State Sensor",
          program_entity: "Program/Cycle Select",
          icon: "Card Icon",
          complete_status_for_x_hours: "Completed Status Duration"
        };
        return labels[schema.name];
      },
      computeHelper: (schema) => {
        const helpers = {
          device_name: "Pick any entity from the washer. LocalThings siblings are found automatically.",
          icon: "Icon to display in the card header (emoji or mdi:icon-name)",
          complete_status_for_x_hours: "Hours to show green 'completed' status after washing is done"
        };
        return helpers[schema.name];
      },
    };
  }
}

customElements.define("samsung-washer-card", SamsungWasherCard);

